namespace spiral_matrix {

std::vector<std::vector<uint32_t>> spiral_matrix(uint32_t size) {
    std::vector<std::vector<uint32_t>> matrix(
        size, std::vector<uint32_t>(size, 0));

    if (size == 0) {
        return matrix;
    }

    int top = 0;
    int bottom = static_cast<int>(size) - 1;
    int left = 0;
    int right = static_cast<int>(size) - 1;
    uint32_t value = 1;

    while (top <= bottom && left <= right) {
        for (int col = left; col <= right; ++col) {
            matrix[static_cast<size_t>(top)][static_cast<size_t>(col)] =
                value++;
        }
        ++top;

        for (int row = top; row <= bottom; ++row) {
            matrix[static_cast<size_t>(row)][static_cast<size_t>(right)] =
                value++;
        }
        --right;

        if (top <= bottom) {
            for (int col = right; col >= left; --col) {
                matrix[static_cast<size_t>(bottom)][static_cast<size_t>(col)] =
                    value++;
            }
            --bottom;
        }

        if (left <= right) {
            for (int row = bottom; row >= top; --row) {
                matrix[static_cast<size_t>(row)][static_cast<size_t>(left)] =
                    value++;
            }
            ++left;
        }
    }

    return matrix;
}

}  // namespace spiral_matrix
